@props(['cases'=>[]])
<div class="table-scroll"><table><thead><tr><th>Account / case</th><th>Document screening</th><th>Admin review</th><th>Submitted</th><th></th></tr></thead><tbody>@forelse($cases as $case)<tr><td><div class="case-account"><span>{{ strtoupper(substr($case['user_id'],0,1)) }}</span><div><strong>{{ substr($case['user_id'],0,8).'...' }}@if(($case['admin_decision'] ?? '')==='pending' && ($case['status'] ?? '')==='document_like' && empty($case['admin_seen_at'])) <span class="pill blue new-badge">New</span>@endif</strong><small>{{ $case['session_id'] ? substr($case['session_id'],0,20).'...' : 'No capture session' }}</small></div></div></td><td><span class="pill {{ $case['status']==='document_like'?'green':($case['status']==='rejected'?'red':'blue') }}">{{ $case['status']==='document_like'?'Document recognized':ucwords(str_replace('_',' ',$case['status'])) }}</span></td><td><span class="pill {{ $case['admin_decision']==='approved'?'green':($case['admin_decision']==='pending'?'amber':'red') }}">{{ ucfirst($case['admin_decision']) }}</span></td><td class="muted">{{ \Illuminate\Support\Carbon::parse($case['created_at'])->format('M d, H:i') }}</td><td>@if(in_array(auth()->user()->role,['reviewer','admin']))<a class="table-action" href="{{ route('reviews.show',$case['user_id']) }}">Review case &#8599;</a>@else<span class="muted">Read-only role</span>@endif</td></tr>@empty<tr><td colspan="5"><div class="empty"><x-icon name="shield"/><h3>No cases in this view</h3><p>New verification sessions will appear when the shared backend is connected and users submit documents.</p></div></td></tr>@endforelse</tbody></table></div>